import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Link, useParams } from '@tanstack/react-router'
import { ArrowLeft, Bell, Bot, CalendarClock, Check, ClipboardList, Coins, Gavel, Gift, Lightbulb, LoaderCircle, MessageSquareReply, PanelsTopLeft, Plus, ScrollText, ShieldAlert, ShieldCheck, Sparkles, Star, Tags, TerminalSquare, Ticket, Trash2, Trophy, UserCheck, UserPlus, Volume2, MailQuestion, Link2, BarChart3, Gauge, Moon } from 'lucide-react'
import { useEffect, useState } from 'react'
import { DiscordChannelSelect } from '../components/discord-channel-select'
import { DiscordChannelMultiSelect } from '../components/discord-channel-multi-select'
import { DiscordRoleSelect } from '../components/discord-role-select'
import { Badge, Button, Panel, Toggle } from '../components/ui'
import { WelcomeMessageEditor } from '../components/welcome-message-editor'
import { getGuildChannels, getGuildConfig, getGuildRoles, getServers, saveGuildConfig } from '../lib/api'
import type { CustomCommand, GuildChannel, GuildConfig, GuildRole } from '../types'

